<?php require_once __DIR__.'/../bootstrap.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['id'];if(isset($_POST['delete']))$pdo->prepare('DELETE FROM video_sources WHERE id=?')->execute([$id]);else{$q=$pdo->prepare('UPDATE video_sources SET language=?,server_name=?,source_type=?,source_url=?,priority=?,active=? WHERE id=?');$q->execute([trim($_POST['language']),trim($_POST['server_name']),$_POST['source_type'],trim($_POST['source_url']),(int)$_POST['priority'],isset($_POST['active'])?1:0,$id]);}header('Location: sources.php');exit;}$s=$pdo->query('SELECT v.*,a.title,e.number FROM video_sources v JOIN anime a ON a.id=v.anime_id JOIN episodes e ON e.id=v.episode_id ORDER BY v.id DESC')->fetchAll();$title='Video sources — AniRead';include __DIR__.'/../includes/header.php';?><h1>Authorized video sources</h1><p><a class="btn" href="source-edit.php">Add source</a></p><table class="table"><tr><th>Anime</th><th>Ep</th><th>Language</th><th>Server</th><th>Type</th><th>Active</th><th></th></tr><?php foreach($s as $v):?><tr><td><?=e($v['title'])?></td><td><?=e($v['number'])?></td><td><?=e($v['language'])?></td><td><?=e($v['server_name'])?></td><td><?=e($v['source_type'])?></td><td><?=$v['active']?'Yes':'No'?></td><td><a class="btn alt" href="source-edit.php?id=<?=$v['id']?>">Edit</a></td></tr><?php endforeach;?></table><?php include __DIR__.'/../includes/footer.php';
